type ControlCommand =
  | { op: 'suspend'; route: string; reason: string }
  | { op: 'resume'; route: string }
  | { op: 'snapshot' };
type ControlReply = { id: string; applied: boolean; status: RouteStatus };

function dispatch(cmd: ControlCommand, id: string): ControlReply {
  switch (cmd.op) {                                    // exhaustive: no default clause
    case 'suspend': return { id, applied: routes.suspend(cmd.route, cmd.reason), status: routes.snapshot() };
    case 'resume':  return { id, applied: routes.resume(cmd.route), status: routes.snapshot() };
    case 'snapshot': return { id, applied: true, status: routes.snapshot() };
  }
}

