const ControlCommand = z.discriminatedUnion('op', [
  z.object({ op: z.literal('suspend'), route: z.string(), reason: z.string() }),
  z.object({ op: z.literal('resume'), route: z.string() }),
]);

const sub = nc.subscribe('control.orders.cmd', { callback: (err, msg) => {
  const parsed = ControlCommand.safeParse(JSON.parse(sc.decode(msg.data)));
  if (!parsed.success) return msg.respond(sc.encode(JSON.stringify({ error: 'invalid-command' })));
  msg.respond(sc.encode(JSON.stringify({ applied: apply(parsed.data), status: snapshot() })));
}});
